$files=@($relativeFiles|ForEach-Object {Join-Path $root $_})+@((Join-Path $Directory 'source-what-if-supplement.json'),(Join-Path $Directory 'source-selfreview.md'),(Join-Path $Directory 'client-boundary.json'),(Join-Path $Directory 'chain-completion.json'))
$observer=[pscustomobject]@{supplied=$false;path=$null;sha256=$null;qualification='No optional runtime observer receipt supplied; no observer execution or result is claimed.'}
$observerText=$observer.qualification
if(-not [string]::IsNullOrWhiteSpace($RuntimeObserverReceipt)){
 $observerPath=[IO.Path]::GetFullPath($RuntimeObserverReceipt)
 $evidenceRoot=(Join-Path $root 'docs/evidence/release15')+[IO.Path]::DirectorySeparatorChar
 if(-not $observerPath.StartsWith($evidenceRoot,[StringComparison]::Ordinal) -or [IO.Path]::GetExtension($observerPath) -cne '.json' -or -not (Test-Path -LiteralPath $observerPath -PathType Leaf)){throw 'Optional observer must be an existing public release15 JSON evidence receipt'}
 $observer=[pscustomobject]@{supplied=$true;path=$observerPath;sha256=(Get-FileHash -LiteralPath $observerPath).Hash;qualification='Additional operational observation only. Inspect its actual source/run/time/command provenance and limitations; it does not establish independent HV or replace required native gates.'}
 $files+=@($observerPath)
 $observerText=$observerPath+' SHA256 '+$observer.sha256+'; '+$observer.qualification
}
$pins=@(foreach($path in $files){[pscustomobject]@{path=$path;sha256=(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash}})
$selfPath=Join-Path $Directory 'source-self-review.json'
$briefPath=Join-Path $Directory 'cline-review-brief.md'
if((Test-Path -LiteralPath $selfPath) -or (Test-Path -LiteralPath $briefPath)){throw 'Retain prior review preparation; do not overwrite'}
$retainedInputs=@(
 [pscustomobject]@{kind='review-preparer';original=$PSCommandPath;path=(Join-Path $Directory 'review-preparer.ps1');sha256=(Get-FileHash -LiteralPath $PSCommandPath).Hash}
 [pscustomobject]@{kind='review-template';original='/tmp/wordpairs-cline-review-brief-template.md';path=(Join-Path $Directory 'review-brief-template.md');sha256=(Get-FileHash -LiteralPath '/tmp/wordpairs-cline-review-brief-template.md').Hash}
)
foreach($inputPin in $retainedInputs){
 if(Test-Path -LiteralPath $inputPin.path){throw 'Retain earlier preparation inputs; do not overwrite'}
 $pins+=[pscustomobject]@{path=$inputPin.path;sha256=$inputPin.sha256}
}
