function Get-ReviewReportText([string]$Name){
 $report=@($reports|Where-Object {$_.name -ceq $Name -or $_.kind -ceq $Name})
 if($report.Count -ne 1){throw "Review report absent or ambiguous: $Name"}
 $report[0]|ConvertTo-Json -Depth 18
}
